package com.gymmind.nutrition.infrastructure.persistence; import com.gymmind.nutrition.domain.model.NutritionPlan; import com.gymmind.nutrition.domain.repository.NutritionPlanRepository; import org.springframework.stereotype.Repository; @Repository class JpaNutritionPlanRepository implements NutritionPlanRepository { final SpringDataNutritionPlanRepository d; JpaNutritionPlanRepository(SpringDataNutritionPlanRepository d){this.d=d;} public NutritionPlan save(NutritionPlan p){return d.save(p);} }
